+            case 1:
+                return new QueryApiKeyRequest(request.getQueryBuilder(),
+                    request.getFrom() + 1,
+                    request.getSize(),
+                    request.getFieldSortBuilders(),
+                    request.getSearchAfterBuilder());
+            case 2:
+                return new QueryApiKeyRequest(request.getQueryBuilder(),
+                    request.getFrom(),
+                    request.getSize() + 1,
+                    request.getFieldSortBuilders(),
+                    request.getSearchAfterBuilder());
+            case 3:
+                return new QueryApiKeyRequest(request.getQueryBuilder(),
